// Convert 3D polygon points to 2D using the given plane
std::vector<Kernel::Point_2> polygon_2d;
polygon_2d.reserve(polygon_coords.size());

for (const auto& coord : polygon_coords) {
  if (coord.size() != 3) {
    throw std::invalid_argument("Each coordinate must have 3 elements (x, y, z)");
  }
  Kernel::Point_3 p3(coord[0], coord[1], coord[2]);
  Kernel::Point_2 p2 = plane.to_2d(p3);
  polygon_2d.push_back(p2);
}

// Insert the 2D points into the triangulation and keep track of handles
std::vector<Triangulation::Vertex_handle> vertices;
vertices.reserve(polygon_2d.size());

Triangulation::Face_handle current_face = walk_start;
for (const auto& p : polygon_2d) {
  // Insert point using the walk_start hint for efficiency
  Triangulation::Vertex_handle vh = triangulation.insert(p, current_face);
  if (vh->point() != p) {
    // Point already existed, find the existing vertex handle
    vh = triangulation.nearest_vertex(p, current_face);
  } else {
    // Update walk_start to the newly inserted face for the next insertion
    // A vertex's incident face is a good starting point for the next insertion
    current_face = vh->face();
  }
  vertices.push_back(vh);
}

// Now insert the constraints (edges) between consecutive vertices
for (size_t i = 0; i < vertices.size(); ++i) {
  size_t next = (i + 1) % vertices.size();
  if (vertices[i] != vertices[next]) {
    triangulation.odd_even_insert_constraint(vertices[i], vertices[next]);
  }
}

// Update walk_start for potential future use (e.g., next polygon)
// Using the face incident to the last vertex is a reasonable choice.
if (!vertices.empty()) {
  walk_start = vertices.back()->face();
}

